<form id="product-main-form" class="grid gap-4 sm:grid-cols-2" @submit.prevent="saveMain"><label class="text-sm font-medium">Название<BaseInput :model-value="form.name" data-autofocus class="mt-1.5" required :placeholder="copiedFromName?'Введите новое название':''" :aria-describedby="copiedFromName?'copied-product-name-help':undefined" :aria-invalid="copiedNameError?'true':undefined" @update:model-value="v=>{form.name=v;copiedNameError='';if(!manuallyEditedSlug)form.slug=slugify(v)}"/><span v-if="copiedFromName" id="copied-product-name-help" class="mt-1.5 block text-xs text-warning-600">Укажите название, отличающееся от «{{copiedFromName}}».</span><span v-if="copiedNameError" class="mt-1.5 block text-xs text-error-500" role="alert">{{copiedNameError}}</span></label><label class="text-sm font-medium">URL (slug)<BaseInput v-model="form.slug" class="mt-1.5" required pattern="[a-z0-9]+(-[a-z0-9]+)*" @update:model-value="manuallyEditedSlug=true"/></label><label class="text-sm font-medium">Категория<BaseSelect v-model="selectedCategory" class="mt-1.5" :options="categoryOptions" placeholder="Выберите категорию" accessible-name="Категория" searchable/></label><label class="text-sm font-medium">Бренд<BaseSelect v-model="selectedBrand" class="mt-1.5" :options="brandOptions" accessible-name="Бренд" searchable/></label><div class="text-sm font-medium"><span id="product-sku-label">SKU</span><p aria-labelledby="product-sku-label" class="mt-1.5 flex min-h-11 items-center rounded-lg border border-gray-200 bg-gray-50 px-3 py-2.5 font-mono text-gray-700">{{editing?.sku??'Будет назначен автоматически после сохранения'}}</p></div><label class="text-sm font-medium">Артикул<BaseInput :model-value="form.article_number??''" class="mt-1.5" @update:model-value="v=>form.article_number=v||null"/></label><label class="text-sm font-medium">Штрихкод<BaseInput :model-value="form.barcode??''" class="mt-1.5" inputmode="numeric" pattern="([0-9]{8}|[0-9]{12,14})" @update:model-value="v=>form.barcode=v||null"/></label><label class="text-sm font-medium">Единица продажи<BaseSelect v-model="form.unit" class="mt-1.5" :options="units" accessible-name="Единица продажи"/></label><label class="text-sm font-medium">Цена<BaseInput v-model="form.price" class="mt-1.5" type="number" min="0" step="0.01" required/></label><label class="text-sm font-medium">Старая цена<BaseInput :model-value="form.old_price??''" class="mt-1.5" type="number" min="0" step="0.01" @update:model-value="v=>form.old_price=v||null"/></label><label class="text-sm font-medium">Остаток<BaseInput :model-value="String(form.stock_quantity)" class="mt-1.5" type="number" min="0" @update:model-value="v=>form.stock_quantity=Number(v)"/></label><BaseCheckbox class="self-end" mode="boolean" :checked="form.is_on_sale" accessible-name="Товар участвует в распродаже" @update:checked="form.is_on_sale=$event">Распродажа</BaseCheckbox><label class="text-sm font-medium sm:col-span-2">Описание<BaseTextarea v-model="form.description" class="mt-1.5"/></label><p class="sm:col-span-2 rounded-lg bg-gray-50 px-3 py-2 text-sm text-gray-500">Новый товар сохранится как черновик. Публикация доступна на шаге «Проверка».</p></form>
